# Let me analyze Demo 2 more carefully by checking what defines each output row
# Output was 4x5, corresponding to horizontal bands

# Key observation: maybe output[r][c] is the DOMINANT non-background value
# found in vertical region c for the content band r

def get_marker_values_at_row(r):
    """Get values at all marker columns for a given row"""
    return {i: demo2_input[r][i] for i in [5, 9, 13, 17, 21, 25]}

def get_content_band(row_idx):
    """Determine which content band a row belongs to"""
    # Band boundaries based on marker rows at 0,5,10,15,20
    if row_idx >= 1 and row_idx < 5:
        return 0
    elif row_idx >= 6 and row_idx < 10:
        return 1
    elif row_idx >= 11 and row_idx < 15:
        return 2
    elif row_idx >= 16 and row_idx < 21:
        return 3
    else:
        return None

# Now for each content band, determine dominant value per vertical region
