for band in range(4):
    # Get representative content row
    rep_rows = []
    if band == 0:
        rep_rows = [1]
    elif band == 1:
        rep_rows = [6]
    elif band == 2:
        rep_rows = [11]
    else:
        rep_rows = [16]

    # What are the marker values around this band?
